#define CDL2H
#define _CRT_SECURE_NO_WARNINGS

#ifndef VALUE
#define VALUE long
#endif

//Add any necessary includes here.
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#ifdef WINDOWS
void debug_pause() {
    system("pause");
}
#else
// No equivalent of system("pause") on Linux and mac, so we just print a message and wait for user input.
void debug_pause() {
    printf("Press Enter to continue...");
    getchar();
}
#endif

// Define the some convenient types and macros for use in generated code. The "#define VALUE  type" (usually "long") is expected to be before this file is included.
#define BOOL VALUE
#define TRUE 1
#define FALSE 0
#define RETURNV(res) return res
#define RETURN return
#define PREDICATE BOOL
#define TEST BOOL
#define ACTION void
#define FUNCTION void
#define PROC
#define MACRO

#define DECLARE_VAR(name,value) \
    VALUE name = value

/* CDL2 Standard Macros for Lists */
#define DECLARE_LIST(name, lwb, upb) \
    VALUE name##_array[(upb) - (lwb) + 1]; \
    VALUE name##_lwb = (lwb); \
    VALUE name##_upb = (upb)
    

#define CDL2_LIST_GET(name, i) \
    ((i) < name##_lwb || (i) > name##_upb ? \
        (fprintf(stderr, "Index out of bounds: %ld not in [%ld..%ld]\\n", (VALUE)(i), name##_lwb, name##_upb), exit(1), 0) : \
        name##_array[(i) - name##_lwb])

#define CDL2_LIST_SET(name, i, value) \
    do { \
        if ((i) < name##_lwb || (i) > name##_upb) { \
            fprintf(stderr, "Index out of bounds: %ld not in [%ld..%ld]\\n", (VALUE)(i), name##_lwb, name##_upb); \
            exit(1); \
        } \
        name##_array[(i) - name##_lwb] = (value); \
    } while(0)

#define CDL2_LIST_SWAP(name, i, j) \
    do { \
        VALUE temp; \
        if ((i) < name##_lwb || (i) > name##_upb || (j) < name##_lwb || (j) > name##_upb) { \
            fprintf(stderr, "Index out of bounds in swap\\n"); \
            exit(1); \
        } \
        temp = name##_array[(i) - name##_lwb]; \
        name##_array[(i) - name##_lwb] = name##_array[(j) - name##_lwb]; \
        name##_array[(j) - name##_lwb] = temp; \
    } while(0)

    

